#!/usr/bin/env python3
"""Generate public records from actual test/process/workload outputs, without private paths."""
import argparse,json,shutil
from pathlib import Path
root=Path(__file__).resolve().parents[1]
p=argparse.ArgumentParser()
for name in ("go_json","smoke","bench","mock"):p.add_argument("--"+name.replace("_","-"),type=Path,required=True)
p.add_argument("--workspace-smoke",type=Path,required=True);p.add_argument("--browser-smoke",type=Path);
p.add_argument("--frontend-tests",type=int,required=True);p.add_argument("--frontend-files",type=int,required=True);a=p.parse_args()
metadata=json.loads((root/"build/BUILD_METADATA.json").read_text())
events=[json.loads(x) for x in a.go_json.read_text().splitlines()]
assert not any(x["Action"]=="fail" for x in events),"failed Go events"
passed=[x for x in events if x["Action"]=="pass" and x.get("Test")]
packages=[x["Package"] for x in events if x["Action"]=="pass" and not x.get("Test")]
top=[x for x in passed if "/" not in x["Test"]]
leaf=[x for x in passed if not any(y["Package"]==x["Package"] and y["Test"].startswith(x["Test"]+"/") for y in passed)]
smoke=json.loads(a.smoke.read_text());bench=json.loads(a.bench.read_text());mock=json.loads(a.mock.read_text())
workspace=json.loads(a.workspace_smoke.read_text());assert all(x["status"]=="passed" for x in workspace["checks"])
browser=json.loads(a.browser_smoke.read_text()) if a.browser_smoke else None
digest=metadata["source_input_sha256"]
assert digest in workspace["version_output"]
if browser:assert browser["source_input_sha256"]==digest and all(x["status"]=="passed" for x in browser["checks"])
assert bench["source_hash"]==digest and mock["source_hash"]==digest and digest in smoke["version_output"],"evidence/build source mismatch"
assert all(x["status"]=="passed" for x in smoke["checks"])
assert mock["mode"]=="mock" and mock["planned"]==16 and mock["actual_requests"]<=40
assert all(x["initiated_ms"]<phase["window_seconds"]*1000 for phase in bench["phases"] for x in phase["samples"]),"requests outside window"
evidence=root/"docs/evidence";evidence.mkdir(parents=True,exist_ok=True)
for src,name in ((a.go_json,"go-race.jsonl"),(a.smoke,"process-smoke.json"),(a.mock,"mock-pilot.json")):shutil.copyfile(src,evidence/name)
bench_summary={k:v for k,v in bench.items() if k!="phases"}
bench_summary["phases"]=[{k:v for k,v in ph.items() if k!="samples"} for ph in bench["phases"]]
shutil.copyfile(a.workspace_smoke,evidence/"personal-workspace-smoke.json")
if a.browser_smoke:shutil.copyfile(a.browser_smoke,evidence/"browser-smoke.json")
(evidence/"performance-summary.json").write_text(json.dumps(bench_summary,ensure_ascii=False,indent=2)+"\n")
record={"software_version":metadata["software_version"],"source_input_sha256":digest,"go_vet":"passed","go_race":{"tested_packages":packages,"top_level_tests":len(top),"leaf_tests":len(leaf),"pass_events_including_subtest_parents":len(passed)},"frontend":{"environment":"Vitest/jsdom; actual command result recorded","tests":a.frontend_tests,"files":a.frontend_files,"production_typescript_vite_build":"passed"},"openapi_operations":37,"guide_codes":len(json.loads((root/"internal/domain/guides.json").read_text())),"process_smoke_checks":len(smoke["checks"])+len(workspace["checks"]),"personal_workspace_checks":len(workspace["checks"]),"browser_checks":len(browser["checks"]) if browser else 0,"mock_pilot":{"trials":mock["planned"],"actual_requests":mock["actual_requests"],"succeeded":sum(t["status"]=="succeeded" for t in mock["trials"]),"human_review":"unreviewed"},"pending":[*([] if browser else ["real browser interaction/layout"]),"native Windows launch/path/exit","Docker image build/TLS/restart/volume","live model pilot/holdout","independent human semantic review","public hosting/remote CI"],"limits":["Tests do not prove absence of every bug","Cross-compilation is not native execution","Mock protocol success is not real model quality"]}
(evidence/"verification-summary.json").write_text(json.dumps(record,ensure_ascii=False,indent=2)+"\n")
lines=[f"# FlowDesk {metadata['software_version']} verification","",f"Source input SHA-256: **{digest}**.",f"Build: {metadata['built_at']}; {metadata['go']}; Node{metadata['node']}. Actual SQLite{bench['sqlite_version']}.","",f"Go vet and race tests passed: **{len(top)} top-level tests, {len(leaf)} leaf cases** across {len(packages)} tested packages. Parent/subtest pass events total{len(passed)}; these counting methods must not be added together. Frontend: **{a.frontend_tests} tests across {a.frontend_files} files** passed in Vitest/jsdom, with strict TypeScript/Vite production build. ","","| Area | Actual evidence |","| --- | --- |","| Business/permissions | requester scope, internal-note filtering, CAS race, exact reply/cycle history, last administrator, revoked epochs |","| Durable mutations | concurrent same-key replay; applied/not-applied/unreadable commit fault injections; no duplicate creation |","| AI/worker | production engine against local HTTP mock, pre-HTTP durable intent and frozen sources, persisted usage/cleared secret, read-only tool bounds and malformed groups |","| Failures | body/header timeout, refusal with available usage, invalid usage, unsafe endpoint/redirect, SQL-only pending-save retry, canceled late output, restart without paid replay |","| Contract | 37 route operations, request/query strictness, real response schemas and generated TypeScript drift check |","| Frontend behavior | new history above older blocks, preserving manual edit, fresh review acknowledgements, exact preview submission, prominent publish success, atomic terminal-job refresh for admin/staff, personal-login isolation, Unicode text import with explicit save, reminder details/X, modal focus, disabled reason, old-session response/export suppression |","| Backup/recovery | canonical Windows file URI, interrupted empty/schema-only initialization, no reseed after lost metadata, read-only diagnosis, WAL snapshot, schema/profile rejection without modifying DB/key, OS lock, three recovery crash stages and missing-temp stop |",f"| Native Linux process | {len(smoke['checks'])+len(workspace['checks'])} executable/HTTP checks, including embedded assets, seed/login/review, session/history after restart, backup, offline password/key recovery, server bootstrap/cookie attributes, startup diagnostics and 0.1.0 upgrade; additional personal-workspace account/model/tool/failure/restart checks and genuine 0.1.1 upgrade |","", "The process smoke used an extracted Linux package and direct HTTP requests, **not a real browser**. Server TLS termination/secure-cookie browser behavior remains a container/platform gate.","","## AI evidence","",f"Frozen synthetic dataset:64 distinct cases (16 development/48 holdout). Mock pilot:16 trials and {mock['actual_requests']} local protocol requests; every trial, failure and unattempted slot is retained. Human semantic fields remain unreviewed. No paid provider call or true-model quality result is claimed.","","## Pending gates","", (f"- Headless Chromium: {len(browser['checks'])} actual browser checks passed; see browser-smoke.json." if browser else "- Real browser layout and complete UI/API interaction."), "- Native Windows first launch, Unicode path, console input, Ctrl+C and persistence.", "- Docker images/digests, clean-room TLS, volume permissions, restart and recovery.", "- Real-model pilot/full holdout and independent human review.", "- Public hosting and remote GitHub Actions execution.","","Linux execution, cross-compilation, jsdom and mocks do not replace these gates. This is a usable technical first version with the listed limits; successful tests do not establish zero bugs.","","Raw safe evidence: [verification-summary.json](evidence/verification-summary.json), [Go race events](evidence/go-race.jsonl), [process smoke](evidence/process-smoke.json), [personal workspace](evidence/personal-workspace-smoke.json), [mock pilot](evidence/mock-pilot.json), [performance summary](evidence/performance-summary.json)."]
(root/"docs/VERIFICATION.md").write_text("\n".join(lines)+"\n")
lines=["# Local performance record","",f"Source: **{digest}**; recorded{bench['created_at']}. {bench['go_version']}, {bench['os']}/{bench['arch']}, SQLite{bench['sqlite_version']}.",f"Reported logical CPUs:{bench['logical_cpus']}, GOMAXPROCS:{bench['gomaxprocs']}, cgroup CPU max:{bench['cgroup_cpu_max']}, memory max:{bench['cgroup_memory_max']}.","","Dataset:1000 fictional tickets and100 public KB articles. Pre-created authenticated session, real net/http/application/SQLite in one isolated temporary process. Closed-loop mix:70% list,20% independent priority writes including revision-refresh GET,10% dashboard. Idempotency-cache retention is omitted in sustained writes and is covered separately by correctness tests. Random seed20261011.","",f"Each level uses {bench['warmup_seconds']:g}s warmup; measurement windows: {[x['window_seconds'] for x in bench['phases']]}seconds. Requests stop at the window boundary; already-started requests drain for up to5s. Raw statuses including network/timeout0 are retained. RPS below counts HTTP requests, not logical user operations.","","| Clients | HTTP requests | Requests/s | p50 ms | p95 ms | p99 ms | Status counts | Timeouts | Drain s |","| ---: | ---: | ---: | ---: | ---: | ---: | --- | ---: | ---: |"]
for x in bench["phases"]:lines.append(f"| {x['concurrency']} | {x['http_requests']} | {x['http_requests_per_second']:.1f} | {x['p50_ms']:.3f} | {x['p95_ms']:.3f} | {x['p99_ms']:.3f} | {x['status_counts']} | {x['timeouts']} | {x['drain_seconds']:.3f} |")
resource=bench["resources"];q=bench["mock_queue"]
lines+=["",f"PBKDF2-HMAC-SHA256{bench['kdf_iterations']} iterations, ten sequential measured derivations after warmup: median{bench['kdf_median_ms']:.2f}ms. This is neither login throughput nor a hash-concurrency test.",f"Sampled shared-process peaks: heap{resource['heap_peak_bytes']}bytes, Linux RSS{resource['linux_rss_peak_bytes']}bytes, goroutines{resource['goroutine_peak']}; both client and server are included.","","## Artificial queue phase","",f"Two workers,50-active cap, local provider250ms artificial delay. Submitted{q['submitted']}; enqueue statuses{q['enqueue_statuses']}; accepted{q['accepted']}; terminal states{q['terminal_statuses']}; recorded calls{q['recorded_calls']}; elapsed{q['elapsed_seconds']:.3f}s; queue empty after drain:{q['queue_empty_after_drain']}.","","These are local closed-loop measurements on this environment, without open-loop arrivals, TLS proxy overhead or a real provider. They do not establish production capacity, simultaneous-user promises, real model speed or commercial benefit.","","Reproduce from source: build frontend, then go run -buildvcs=false ./cmd/flowdesk-bench --warmup 10s --duration 30s --concurrency 1,10,25 --out new-bench.json. Raw per-request samples are in the separate verification evidence archive; the source package keeps the summary."]
(root/"docs/PERFORMANCE.md").write_text("\n".join(lines)+"\n")
print(json.dumps({k:record[k] for k in ("go_race","frontend","process_smoke_checks","personal_workspace_checks","browser_checks","guide_codes","mock_pilot")},ensure_ascii=False))

